SELECT sessions.browser, ROUND(AVG(web_events.duration_sec), 2) AS avg_duration_sec, MAX(web_events.event_time) AS latest_event_time FROM web_events FULL OUTER JOIN sessions ON web_events.session_id = sessions.id WHERE web_events.event_time < '2023-04-19' GROUP BY sessions.browser HAVING ROUND(AVG(web_events.duration_sec), 2) >= 66 ORDER BY latest_event_time DESC, browser ASC LIMIT 50;
